import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("NO")
        return

    n = int(data[0])

    if n == 0:
        print("NO")
        return

    if n == 1:
        if len(data) < 2:
            print("YES")
            return
        edges_data = data[1:]
        try:
            edge_count = int(edges_data[0])
        except:
            print("NO")
            return
        if edge_count == 0:
            print("YES")
            return
        else:
            print("NO")
            return

    edges_data = data[1:]

    if len(edges_data) < 1:
        print("NO")
        return

    try:
        m = int(edges_data[0])
    except:
        print("NO")
        return

    if m != n - 1:
        print("NO")
        return

    if len(edges_data) - 1 != 2 * (n - 1):
        print("NO")
        return

    edges = []
    idx = 1
    for i in range(m):
        if idx + 1 >= len(edges_data):
            print("NO")
            return
        u = int(edges_data[idx])
        v = int(edges_data[idx + 1])
        edges.append((u, v))
        idx += 2

    adj = {}
    in_degree = {}
    out_degree = {}

    for u, v in edges:
        if u not in adj:
            adj[u] = []
        if v not in adj:
            adj[v] = []
        adj[u].append(v)
        if u not in out_degree:
            out_degree[u] = 0
        if v not in in_degree:
            in_degree[v] = 0
        out_degree[u] += 1
        in_degree[v] += 1

    root = None
    for u in adj:
        if u not in in_degree or in_degree[u] == 0:
            if root is None:
                root = u
            else:
                print("NO")
                return

    if root is None:
        print("NO")
        return

    for u in out_degree:
        if out_degree[u] > 2:
            print("NO")
            return

    visited = set()
    queue = deque([root])
    visited.add(root)

    while queue:
        u = queue.popleft()
        if u in adj:
            for v in adj[u]:
                if v in visited:
                    print("NO")
                    return
                visited.add(v)
                queue.append(v)

    if len(visited) != n:
        print("NO")
        return

    print("YES")

if __name__ == "__main__":
    main()
